  "welcome.subheading": "ਆਪਣੀ ਵਸਤੂ-ਸੂਚੀ ਨੂੰ ਆਪਣੇ ਤਰੀਕੇ ਨਾਲ ਪ੍ਰਬੰਧਿਤ ਕਰੋ।",
  "welcome.intro": "ਭਾਵੇਂ ਤੁਹਾਨੂੰ ਇੱਕ ਸਧਾਰਨ ਮੋਬਾਈਲ ਵਸਤੂ-ਸੂਚੀ ਸਾਥੀ ਚਾਹੀਦਾ ਹੋਵੇ ਜਾਂ ਤੁਹਾਡੇ ਵਧ ਰਹੇ ਕਾਰੋਬਾਰ ਲਈ ਇੱਕ ਪੂਰੀ ਵਸਤੂ-ਸੂਚੀ ਪ੍ਰਬੰਧਨ ਪ੍ਰਣਾਲੀ, Luminous StockHaven ਕੋਲ ਤੁਹਾਡੇ ਲਈ ਵਿਕਲਪ ਹਨ।",
