  "welcome.inventoryWaiting": "ਅਤੇ ਤੁਹਾਡੀ ਵਸਤੂ-ਸੂਚੀ ਬਿਲਕੁਲ ਉੱਥੇ ਹੀ ਹੈ ਜਿੱਥੇ ਤੁਸੀਂ ਇਸ ਨੂੰ ਛੱਡਿਆ ਸੀ।",
  "thankYou.unverified.notVerified": "Stripe ਨੇ ਅਜੇ ਇਸ ਚੈੱਕਆਉਟ ਨੂੰ ਸੈੱਟ ਕਰਨਾ ਪੂਰਾ ਨਹੀਂ ਕੀਤਾ ਹੈ। ਤੁਹਾਡਾ ਭੁਗਤਾਨ ਸੁਰੱਖਿਅਤ ਹੈ — ਕੁਝ ਵੀ ਦੋ ਵਾਰ ਚਾਰਜ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਸੀਂ ਜਾਂਚ ਕਰਦੇ ਰਹਾਂਗੇ।",
  "thankYou.unverified.trialNotEligible": "ਇਸ ਈਮੇਲ ਨੇ ਪਹਿਲਾਂ ਹੀ ਆਪਣੀ ਇੱਕ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਵਰਤ ਲਈ ਹੈ, ਇਸ ਲਈ ਅਜ਼ਮਾਇਸ਼ ਸ਼ੁਰੂ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕੀ। ਜੇ ਤੁਹਾਨੂੰ ਲੱਗਦਾ ਹੈ ਕਿ ਇਹ ਕੋਈ ਗਲਤੀ ਹੈ ਤਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "thankYou.unverified.noPendingCheckout": "ਅਸੀਂ ਇਸ ਵਰਕਸਪੇਸ ਲਈ ਕੋਈ ਬਕਾਇਆ ਚੈੱਕਆਉਟ ਨਹੀਂ ਲੱਭ ਸਕੇ।",
  "thankYou.unverified.default": "ਤੁਹਾਡੀ ਖਰੀਦ ਦੀ ਅਜੇ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋਈ ਹੈ। ਅਸੀਂ ਜਾਂਚ ਕਰਦੇ ਰਹਾਂਗੇ — ਹੋਰ ਚੈੱਕਆਉਟ ਸ਼ੁਰੂ ਨਾ ਕਰੋ।",
  "thankYou.grantedTitle": "ਤੁਸੀਂ ਅੰਦਰ ਹੋ — ਤੁਹਾਡੀ ਯੋਜਨਾ ਵਿੱਚ ਤੁਹਾਡਾ ਸੁਆਗਤ ਹੈ।",
  "thankYou.trialRunning": "ਤੁਹਾਡੀ 7-ਦਿਨ ਦੀ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ {date} ਤੱਕ ਚੱਲ ਰਹੀ ਹੈ। ਅਜ਼ਮਾਇਸ਼ ਖਤਮ ਹੋਣ ਤੱਕ ਤੁਹਾਡੇ ਤੋਂ ਕੋਈ ਚਾਰਜ ਨਹੀਂ ਲਿਆ ਜਾਵੇਗਾ।",
