  "thankYou.noSessionBody": "ਇਹ ਪੰਨਾ Stripe ਚੈੱਕਆਉਟ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ। ਜੇ ਤੁਸੀਂ ਗਾਹਕੀ ਲੈ ਰਹੇ ਸੀ, ਤਾਂ ਯੋਜਨਾਵਾਂ ਵਾਲੇ ਪੰਨੇ ਤੋਂ ਸ਼ੁਰੂ ਕਰੋ — ਕੁਝ ਵੀ ਚਾਰਜ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ।",
