  "thankYou.pendingTitle": "ਤੁਹਾਡੀ ਖਰੀਦ ਦੀ ਅਜੇ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋਈ ਹੈ।",
  "thankYou.checkingBody": "ਅਸੀਂ Stripe ਨਾਲ ਤੁਹਾਡੀ ਗਾਹਕੀ ਦੀ ਪੁਸ਼ਟੀ ਕਰ ਰਹੇ ਹਾਂ। ਇਸ ਵਿੱਚ ਆਮ ਤੌਰ 'ਤੇ ਕੁਝ ਸਕਿੰਟ ਲੱਗਦੇ ਹਨ — ਕਿਰਪਾ ਕਰਕੇ ਇਹ ਪੰਨਾ ਖੁੱਲ੍ਹਾ ਰੱਖੋ।",
  "thankYou.serverVerified": "ਤੁਹਾਡੀ ਯੋਜਨਾ ਸਰਵਰ-ਪੁਸ਼ਟੀ ਕੀਤੇ ਪ੍ਰਦਾਤਾ ਰਿਕਾਰਡਾਂ ਦੁਆਰਾ ਨਿਰਧਾਰਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਖਰੀਦ ਦੀ ਪੁਸ਼ਟੀ ਹੋਣ ਤੱਕ ਐਪ ਅਨਲੌਕ ਨਹੀਂ ਹੁੰਦੀ।",
