  "plans.priceNote": "Essentials $14.99/ਮਹੀਨਾ ਹੈ ਅਤੇ ਲਾਗੂ ਟੈਕਸ, ਜੇ ਕੋਈ ਹੋਣ। Business $29.99/ਮਹੀਨਾ ਹੈ ਅਤੇ ਲਾਗੂ ਟੈਕਸ, ਜੇ ਕੋਈ ਹੋਣ। ਕੋਈ ਵੀ ਲੋੜੀਂਦਾ ਟੈਕਸ ਪ੍ਰਦਾਤਾ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਨਿਰਧਾਰਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਭੁਗਤਾਨ ਤੋਂ ਪਹਿਲਾਂ ਅੰਤਿਮ ਕੁੱਲ ਵਿੱਚ ਦਿਖਾਈ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ। ਇਹ ਤੁਲਨਾ ਪੰਨਾ ਟੈਕਸ ਦਾ ਅਨੁਮਾਨ ਜਾਂ ਭੁਗਤਾਨ ਅਧਿਕਾਰ ਨਹੀਂ ਹੈ।",
  "plans.mobilePriceNote": "ਸਿਰਫ਼-ਮੋਬਾਈਲ ਯੋਜਨਾ ਆਪਣੀ ਇਰਾਦਾ ਅਮਰੀਕੀ ਮੂਲ ਕੀਮਤ 'ਤੇ $4.99/ਮਹੀਨਾ ਹੈ। App Store ਜਾਂ Google Play ਖਰੀਦ ਤੋਂ ਪਹਿਲਾਂ ਅਸਲ ਸਥਾਨਕ ਗਾਹਕੀ ਕੀਮਤ ਅਤੇ ਲਾਗੂ ਟੈਕਸ ਵਿਖਾਉਂਦਾ ਹੈ। ਇਸ ਦੇ ਉਤਪਾਦ, ਸਾਈਟ ਅਤੇ ਸਟਾਫ਼ ਭੱਤੇ ਲਾਂਚ 'ਤੇ ਸੈੱਟ ਕੀਤੇ ਜਾਂਦੇ ਹਨ, ਵੈੱਬਸਾਈਟ ਪੱਧਰਾਂ ਤੋਂ ਵੱਖਰੇ ਤੌਰ 'ਤੇ।",
  "plans.planChangeNote": "ਵੈੱਬਸਾਈਟ ਯੋਜਨਾ ਬਦਲਾਅ ਦੀ ਪੁਸ਼ਟੀ ਬਿਲਿੰਗ ਪ੍ਰਦਾਤਾ ਦੁਆਰਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ। ਬਦਲਾਅ ਨੂੰ ਅਧਿਕਾਰਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਨਵੀਂ ਕੀਮਤ, ਪ੍ਰਭਾਵੀ ਮਿਤੀ ਅਤੇ ਕੋਈ ਵੀ ਅਨੁਪਾਤੀ ਵਿਵਸਥਾ ਸਮਝਾਈ ਜਾਵੇਗੀ। ਅੱਪਗ੍ਰੇਡ ਨਾਲ ਦੂਜੀ ਗਾਹਕੀ ਨਹੀਂ ਬਣਨੀ ਚਾਹੀਦੀ।",
  "plans.providerNote": "ਕੀਮਤਾਂ, ਚਾਰਜ ਅਤੇ ਅਜ਼ਮਾਇਸ਼ਾਂ ਉਸ ਪ੍ਰਦਾਤਾ ਦੁਆਰਾ ਸੰਭਾਲੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਜਿਸ ਰਾਹੀਂ ਤੁਸੀਂ ਗਾਹਕੀ ਲੈਂਦੇ ਹੋ — App Store, Google Play, ਵੈੱਬਸਾਈਟ ਜਾਂ Shopify — ਇਸ ਪੰਨੇ ਦੁਆਰਾ ਕਦੇ ਨਹੀਂ।",
