  "plans.prelaunchCheckinBody": "ਤੁਹਾਡੀ ਸੱਤ-ਦਿਨ ਦੀ ਝਲਕ ਜਾਂਚ {date} ਹੈ। ਇਹ ਸਿਰਫ਼ ਇੱਕ ਯਾਦ-ਪੱਤਰ ਮੀਲਪੱਥਰ ਹੈ: ਮੁਫ਼ਤ ਪਹੁੰਚ ਜਾਰੀ ਰਹਿੰਦੀ ਹੈ, ਅਤੇ ਕੋਈ ਭੁਗਤਾਨ ਨਿਰਧਾਰਤ ਨਹੀਂ ਹੈ।",
  "plans.trialEndReminder": "ਤੁਹਾਡੀ ਦਰਜ ਅਜ਼ਮਾਇਸ਼ ਸਮਾਪਤੀ {date} ਹੈ। ਹੇਠਾਂ ਰੱਦ ਕਰਨ ਦੀਆਂ ਸ਼ਰਤਾਂ ਵੇਖੋ। ਇਹ ਯਾਦ-ਪੱਤਰ ਕਿਸੇ ਨਿਰਧਾਰਤ ਚਾਰਜ ਦੀ ਜਾਂ ਭੁਗਤਾਨ ਵਿਧੀ ਦੇ ਫਾਈਲ 'ਤੇ ਹੋਣ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕਰਦਾ।",
