  "plans.priceNoteGrandfathered": "ਸਿਰਫ਼ ਸੂਚੀਬੱਧ ਯੋਜਨਾ ਕੀਮਤ — ਤੁਹਾਡੀ ਮੁਫ਼ਤ ਪ੍ਰੀ-ਲਾਂਚ ਪਹੁੰਚ ਲਈ ਕੋਈ ਚਾਰਜ ਨਹੀਂ ਲਿਆ ਜਾਂਦਾ।",
