  "plans.trialNoticeOneDay": "ਤੁਹਾਡੀ ਅਜ਼ਮਾਇਸ਼ ਖਤਮ ਹੋਣ ਵਿੱਚ 24 ਘੰਟੇ ਬਾਕੀ ਹਨ।",
