  "upgrade.intro": "ਯੋਗ ਨਵੇਂ ਗਾਹਕਾਂ ਨੂੰ ਪ੍ਰਤੀ ਖਾਤਾ ਇੱਕ {days}-ਦਿਨ ਦੀ ਅਜ਼ਮਾਇਸ਼ ਮਿਲ ਸਕਦੀ ਹੈ, ਪ੍ਰਤੀ ਯੋਜਨਾ ਇੱਕ ਅਜ਼ਮਾਇਸ਼ ਨਹੀਂ। Essentials ਤੋਂ Business ਵਿੱਚ ਬਦਲਣ ਨਾਲ ਕੋਈ ਹੋਰ ਮੁਫ਼ਤ ਅਜ਼ਮਾਇਸ਼ ਕਦੇ ਸ਼ੁਰੂ ਨਹੀਂ ਹੁੰਦੀ। ਤੁਸੀਂ ਇਸ 'ਤੇ ਹੋ",
  "upgrade.introGrandfathered": " — ਇੱਕ ਪੂਰਾ Business ਵਰਕਸਪੇਸ, ਬਿਨਾਂ ਕਿਸੇ ਚਾਰਜ ਦੇ।",
