  "upgrade.introPeriod": "।",
  "upgrade.pastDueTitle": "ਭੁਗਤਾਨ ਬਕਾਇਆ",
  "upgrade.pastDueBody": "ਤੁਹਾਡਾ ਪਿਛਲਾ ਭੁਗਤਾਨ ਨਹੀਂ ਹੋਇਆ, ਇਸ ਲਈ ਇਹ ਗਾਹਕੀ ਬਕਾਇਆ ਹੈ। ਹੇਠਾਂ ਆਪਣੀ ਭੁਗਤਾਨ ਵਿਧੀ ਅੱਪਡੇਟ ਕਰੋ — Stripe ਆਪਣੇ ਸਮਾਂ-ਸਾਰਣੀ ਅਨੁਸਾਰ ਆਪਣੇ ਆਪ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੇਗਾ, ਅਤੇ ਤੁਹਾਡੀ ਗਾਹਕੀ ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਰੱਦ ਨਹੀਂ ਕੀਤੀ ਜਾਵੇਗੀ। ਜੇ ਤੁਹਾਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ, ਤਾਂ ਈਮੇਲ ਕਰੋ",
