  "upgrade.downgradeWarning2": "ਵਾਧੂ ਕਾਰੋਬਾਰ ਅਤੇ ਸਟੋਰ (2, 3, 4, 5 — ਪਹਿਲੇ ਤੋਂ ਇਲਾਵਾ ਜਿੰਨੇ ਵੀ ਹੋਣ) ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ ਰਹਿਣਗੇ।",
  "upgrade.downgradeWarning3": "ਨਿਰਯਾਤ ਖਤਮ ਹੋ ਜਾਂਦਾ ਹੈ — ਕੋਈ CSV/Excel ਨਿਰਯਾਤ ਨਹੀਂ, ਸਿਰਫ਼ ਆਯਾਤ।",
