  "upgrade.dialogDowngradeDesc": "ਡਾਊਨਗ੍ਰੇਡ ਕਰਨ ਨਾਲ ਤੁਹਾਡਾ ਡਾਟਾ ਕਦੇ ਮਿਟਦਾ ਨਹੀਂ ਹੈ — ਪਰ ਇਸ ਦਾ ਕੁਝ ਹਿੱਸਾ ਪਹੁੰਚ ਤੋਂ ਬਾਹਰ ਹੋ ਜਾਂਦਾ ਹੈ। ਪਹਿਲਾਂ ਇਹ ਪੜ੍ਹੋ।",
