  "billing.cancel.oneTrialRest": "ਅਜ਼ਮਾਇਸ਼ ਜਾਂ ਗਾਹਕੀ ਰੱਦ ਕਰਨ ਨਾਲ ਕੋਈ ਹੋਰ ਅਜ਼ਮਾਇਸ਼ ਨਹੀਂ ਮਿਲਦੀ; ਵਾਪਸ ਆਉਣ ਵਾਲੇ ਗਾਹਕਾਂ ਨੂੰ ਭੁਗਤਾਨ ਵਾਲੀ ਗਾਹਕੀ ਚੁਣਨੀ ਚਾਹੀਦੀ ਹੈ।",
