  "billing.cancelError.invalidRequest": "ਅਸੀਂ ਇਹ ਨਹੀਂ ਸਮਝ ਸਕੇ ਕਿ ਕਿਹੜੀ ਗਾਹਕੀ ਰੱਦ ਕਰਨੀ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.businessIdRequired": "ਅਸੀਂ ਇਹ ਨਹੀਂ ਸਮਝ ਸਕੇ ਕਿ ਕਿਹੜੀ ਗਾਹਕੀ ਰੱਦ ਕਰਨੀ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.subscriptionOwnerRequired": "ਸਿਰਫ਼ ਕਾਰੋਬਾਰ ਮਾਲਕ ਹੀ ਇਸ ਗਾਹਕੀ ਨੂੰ ਰੱਦ ਕਰ ਸਕਦਾ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ।",
  "billing.cancelError.billingRecordsNeedReview": "ਇਸ ਨੂੰ ਰੱਦ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਬਿਲਿੰਗ ਰਿਕਾਰਡਾਂ ਦੀ ਸਮੀਖਿਆ ਦੀ ਲੋੜ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.complimentaryAccessProtected": "ਇਸ ਵਰਕਸਪੇਸ ਕੋਲ ਮੁਫ਼ਤ ਪਹੁੰਚ ਹੈ, ਇਸ ਲਈ ਰੱਦ ਕਰਨ ਲਈ ਕੋਈ ਭੁਗਤਾਨ ਵਾਲੀ ਗਾਹਕੀ ਨਹੀਂ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ।",
  "billing.cancelError.noVerifiedSubscriptionRecord": "ਅਸੀਂ ਇਸ ਕਾਰੋਬਾਰ ਲਈ ਕੋਈ ਪੁਸ਼ਟੀ ਕੀਤੀ ਗਾਹਕੀ ਨਹੀਂ ਲੱਭ ਸਕੇ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.purchaseContractMismatch": "ਬਿਲਿੰਗ ਰਿਕਾਰਡ ਇਸ ਕਾਰੋਬਾਰ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ, ਇਸ ਲਈ ਅਸੀਂ ਇਸ ਨੂੰ ਇੱਥੇ ਰੱਦ ਨਹੀਂ ਕਰ ਸਕਦੇ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
