  "billing.cancelError.subscriptionEventHistoryIncomplete": "ਇਸ ਨੂੰ ਰੱਦ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਬਿਲਿੰਗ ਇਤਿਹਾਸ ਦੀ ਸਮੀਖਿਆ ਦੀ ਲੋੜ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.eventRequiresReview": "ਇਸ ਨੂੰ ਰੱਦ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਬਿਲਿੰਗ ਇਤਿਹਾਸ ਦੀ ਸਮੀਖਿਆ ਦੀ ਲੋੜ ਹੈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਕਿਰਪਾ ਕਰਕੇ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.cancelError.subscriptionCancellationUnavailable": "ਰੱਦ ਕਰਨਾ ਪੂਰਾ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ ਗਿਆ — ਤੁਹਾਡੀ ਗਾਹਕੀ ਅਤੇ ਪਹੁੰਚ ਬਿਲਕੁਲ ਉਵੇਂ ਹੀ ਹਨ ਜਿਵੇਂ ਉਹ ਸਨ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "billing.readiness.ariaLabel": "ਅਸਲ Essentials ਚੈੱਕਆਉਟ ਤਿਆਰੀ",
  "billing.readiness.title": "Essentials ਚੈੱਕਆਉਟ — ਅਸਲ ਖਾਤਾ ਸੁਰੱਖਿਆ ਜਾਂਚ",
  "billing.readiness.body": "ਕੁਝ ਵੀ ਖਰੀਦੇ ਬਿਨਾਂ ਅਸਲ ਗਾਹਕੀ ਅਤੇ ਅਜ਼ਮਾਇਸ਼ ਰਿਕਾਰਡਾਂ ਦੀ ਜਾਂਚ ਕਰੋ। ਤੁਹਾਡਾ ਮੁਫ਼ਤ Business ਖਾਤਾ ਅਤੇ ਤੁਹਾਡਾ ਪਜਾਮਾ ਨਮੂਨਾ ਅਪਰਿਵਰਤਿਤ ਰਹਿੰਦੇ ਹਨ। ਇਹ Stripe ਚੈੱਕਆਉਟ ਨਹੀਂ ਖੋਲ੍ਹਦਾ, ਕਾਰਡ ਚਾਰਜ ਨਹੀਂ ਕਰਦਾ, ਜਾਂ ਯੋਜਨਾ ਨਹੀਂ ਬਦਲਦਾ।",
  "billing.readiness.checking": "ਖਾਤਾ ਰਿਕਾਰਡਾਂ ਦੀ ਜਾਂਚ ਹੋ ਰਹੀ ਹੈ…",
  "billing.readiness.inspect": "ਚੈੱਕਆਉਟ ਤਿਆਰੀ ਦੀ ਜਾਂਚ ਕਰੋ (ਕੋਈ ਚਾਰਜ ਨਹੀਂ)",
  "billing.readiness.unknown": "ਸਿਰਫ਼-ਪੜ੍ਹਨ ਵਾਲੀ ਜਾਂਚ ਤਿਆਰੀ ਸਥਾਪਤ ਨਹੀਂ ਕਰ ਸਕੀ ({state})। ਕੁਝ ਵੀ ਨਹੀਂ ਬਦਲਿਆ।",
  "billing.readiness.ready": "Stripe ਚੈੱਕਆਉਟ ਤਿਆਰ ਹੈ — ਕੁੰਜੀਆਂ, ਵੈੱਬਹੁੱਕ ਪੁਸ਼ਟੀ, ਅਤੇ ਪ੍ਰਮਾਣੀਕਰਨ ਸਭ ਦੀ ਪੁਸ਼ਟੀ ਹੋ ਗਈ ਹੈ।",
  "billing.readiness.complimentaryProtected": "ਤੁਹਾਡਾ ਮੁਫ਼ਤ Business ਵਰਕਸਪੇਸ ਸੁਰੱਖਿਅਤ ਹੈ। ਇਹ ਭੁਗਤਾਨ ਵਾਲਾ Essentials ਟੈਸਟ ਖਾਤਾ ਨਹੀਂ ਬਣਨਾ ਚਾਹੀਦਾ।",
  "billing.readiness.environmentIncomplete": "Stripe ਚੈੱਕਆਉਟ ਪ੍ਰਮਾਣ-ਪੱਤਰ, ਵੈੱਬਹੁੱਕ ਪੁਸ਼ਟੀ ਜਾਂ ਐਪ ਵਾਪਸੀ ਪਤੇ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋ ਸਕੀ। ਕੋਈ ਚੈੱਕਆਉਟ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਦਾ।",
  "billing.readiness.ownerHasHistory": "ਇਸ ਮਾਲਕ ਕੋਲ ਪਹਿਲਾਂ ਦੀ ਗਾਹਕੀ ਜਾਂ ਅਜ਼ਮਾਇਸ਼ ਦਾ ਸਬੂਤ ਹੈ। ਦੂਜਾ ਚੈੱਕਆਉਟ ਨਹੀਂ ਬਣਾਇਆ ਜਾਣਾ ਚਾਹੀਦਾ।",
  "billing.readiness.trialAlreadyUsed": "ਇੱਕ ਸ਼ੁਰੂਆਤੀ ਅਜ਼ਮਾਇਸ਼ ਪਹਿਲਾਂ ਹੀ ਵਰਤੀ ਜਾਂ ਰਾਖਵੀਂ ਕੀਤੀ ਜਾ ਚੁੱਕੀ ਹੈ। ਕੋਈ ਦੁਹਰਾਈ ਅਜ਼ਮਾਇਸ਼ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਦੀ।",
