  "billing.readiness.testModeUnverified": "ਖਾਤਾ ਰਿਕਾਰਡ ਪੜ੍ਹੇ ਜਾ ਸਕਦੇ ਹਨ, ਪਰ ਸੁਰੱਖਿਅਤ Stripe ਟੈਸਟ-ਮੋਡ ਨਿਯੰਤਰਣ ਅਤੇ ਭੁਗਤਾਨ-ਨਵੀਨੀਕਰਨ ਪੂਰਤੀ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋਈ ਹੈ। ਚੈੱਕਆਉਟ ਬੰਦ ਰਹਿੰਦਾ ਹੈ।",
  "billing.readiness.entitlementNotUnique": "ਮੌਜੂਦਾ ਯੋਜਨਾ ਜਾਣਕਾਰੀ ਗੁੰਮ ਹੈ ਜਾਂ ਅਸਪਸ਼ਟ ਹੈ। ਕੋਈ ਚੈੱਕਆਉਟ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਦਾ।",
