  "billing.dryRun.ariaLabel": "ਟੈਸਟ ਅੱਪਗ੍ਰੇਡ ਸਿਮੂਲੇਸ਼ਨ",
  "billing.dryRun.title": "Essentials → Business — ਅਭਿਆਸ ਸਿਮੂਲੇਸ਼ਨ",
  "billing.dryRun.body": "ਇਸ ਬ੍ਰਾਊਜ਼ਰ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕਾਲਪਨਿਕ ਰਿਕਾਰਡਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਪ੍ਰਸਤਾਵਿਤ ਅੱਪਗ੍ਰੇਡ ਨਿਯਮਾਂ ਦਾ ਅਭਿਆਸ ਕਰੋ। ਇਹ ਤੁਹਾਡੇ ਅਸਲ TEST — Pajama Pants ਨਮੂਨੇ, ਤੁਹਾਡੇ ਮੌਜੂਦਾ Business ਵਰਕਸਪੇਸ, Stripe, ਅਜ਼ਮਾਇਸ਼ਾਂ, ਗਾਹਕੀਆਂ ਜਾਂ ਵਸਤੂ-ਸੂਚੀ ਨੂੰ ਨਹੀਂ ਪੜ੍ਹਦਾ ਅਤੇ ਨਹੀਂ ਬਦਲਦਾ।",
  "billing.dryRun.runButton": "ਸਥਾਨਕ ਅੱਪਗ੍ਰੇਡ ਸਿਮੂਲੇਸ਼ਨ ਚਲਾਓ (ਕੋਈ ਚਾਰਜ ਨਹੀਂ)",
  "billing.dryRun.passed": "ਕਾਲਪਨਿਕ ਦ੍ਰਿਸ਼ ਨੇ ਆਪਣੀਆਂ ਸਥਾਨਕ ਜਾਂਚਾਂ ਪਾਸ ਕਰ ਲਈਆਂ",
  "billing.dryRun.blocked": "ਕਾਲਪਨਿਕ ਦ੍ਰਿਸ਼ ਬੰਦ ਕਰ ਦਿੱਤਾ ਗਿਆ",
  "billing.dryRun.example": "ਉਦਾਹਰਨ: Essentials ($14.99/ਮਹੀਨਾ) → Business ($29.99/ਮਹੀਨਾ), ਕਿਸੇ ਵੀ ਲਾਗੂ ਟੈਕਸ ਤੋਂ ਪਹਿਲਾਂ।",
  "billing.dryRun.preserved": "ਉਹੀ ਗਾਹਕੀ ਬਣਾਈ ਰੱਖੀ ਗਈ, ਇੱਕ ਮੂਲ ਅਜ਼ਮਾਇਸ਼ ਬਣਾਈ ਰੱਖੀ ਗਈ, ਅਤੇ ਸਿਮੂਲੇਟ ਕੀਤੀ ਪਜਾਮਾ ਵਸਤੂ-ਸੂਚੀ ਅਪਰਿਵਰਤਿਤ ਰਹੀ। ਉਦਾਹਰਨ ਗਾਹਕ Essentials 'ਤੇ ਰਹਿੰਦਾ ਹੈ ਜਦ ਤੱਕ ਅਸਲ, ਪ੍ਰਦਾਤਾ-ਪੁਸ਼ਟੀ ਕੀਤਾ ਭੁਗਤਾਨ ਨਵੀਨੀਕਰਨ ਪਹੁੰਚ ਬਦਲਣ ਨੂੰ ਜਾਇਜ਼ ਨਹੀਂ ਠਹਿਰਾਉਂਦਾ।",
  "billing.dryRun.limitations": "ਸਥਾਨਕ ਸਿਮੂਲੇਸ਼ਨ Stripe ਗਾਹਕੀ ਬਦਲਾਅ, ਭੁਗਤਾਨ, ਵੈੱਬਹੁੱਕ, ਟੈਕਸ-ਸਮੇਤ ਹਵਾਲੇ, ਲਾਈਵ ਗਾਹਕੀ ਜਾਂ ਤੁਹਾਡੇ ਅਸਲ ਕਾਰੋਬਾਰ ਰਿਕਾਰਡਾਂ ਦੀ ਜਾਂਚ ਨਹੀਂ ਕਰਦਾ।",
