  "exports.eyebrow": "ਡੇਟਾ",
  "exports.title": "ਨਿਰਯਾਤ ਅਤੇ ਬੈਕਅੱਪ",
  "exports.subtitleStart": "ਡਾਊਨਲੋਡ ਹਮੇਸ਼ਾ ਸੀਮਤ ਹੁੰਦੇ ਹਨ",
  "exports.subtitleRest": ". ਹਰ ਫ਼ਾਈਲ 'ਤੇ ਕਾਰੋਬਾਰ ਦਾ ਨਾਂ ਅਤੇ ਉਸ ਦੇ ਬਣਾਏ ਜਾਣ ਦੀ ਤਾਰੀਖ਼ ਲਿਖੀ ਹੁੰਦੀ ਹੈ।",
  "exports.createBusinessFirst": "ਪਹਿਲਾਂ ਕਾਰੋਬਾਰ ਬਣਾਓ — ਨਿਰਯਾਤ ਕਿਸੇ ਕਾਰੋਬਾਰ ਦੇ ਹੁੰਦੇ ਹਨ, ਐਪ ਦੇ ਨਹੀਂ।",
  "exports.lockedTitle": "CSV ਅਤੇ Excel ਨਿਰਯਾਤ Business ਵਿਸ਼ੇਸ਼ਤਾ ਹੈ",
  "exports.lockedDesc": "ਤੁਹਾਡਾ ਵਰਕਸਪੇਸ Essentials ਪਲਾਨ 'ਤੇ ਹੈ। Business ਵਿੱਚ CSV ਅਤੇ Excel ਨਿਰਯਾਤ, ਸਟਾਕ ਮੁਲਾਂਕਣ, ਅਸੀਮਤ ਉਤਪਾਦ ਅਤੇ ਸਟਾਫ਼, ਸਪਲਾਇਰ, ਖਰੀਦਦਾਰੀ ਅਤੇ ਬੰਡਲ ਸ਼ਾਮਲ ਹੁੰਦੇ ਹਨ।",
  "exports.seeBusiness": "ਵੇਖੋ Business ਵਿੱਚ ਕੀ-ਕੀ ਸ਼ਾਮਲ ਹੈ",
  "exports.whatTheseAre": "ਇਹ ਫ਼ਾਈਲਾਂ ਕੀ ਹਨ",
  "exports.about1": "ਹਰ ਡੇਟਾਸੈੱਟ CSV ਜਾਂ ਅਸਲੀ Excel ਵਰਕਬੁੱਕ (.xlsx) ਵਜੋਂ ਆਉਂਦਾ ਹੈ — ਪੂਰੀ ਇਨਵੈਂਟਰੀ ਵਰਕਬੁੱਕ ਸਿਰਫ਼ Excel ਵਿੱਚ ਹੈ, ਹਰ ਡੇਟਾਸੈੱਟ ਲਈ ਇੱਕ ਸ਼ੀਟ ਦੇ ਨਾਲ। CSV ਫ਼ਾਈਲਾਂ Excel, Numbers, Google Sheets ਅਤੇ ਜ਼ਿਆਦਾਤਰ ਸਟਾਕ ਐਪਾਂ ਵਿੱਚ ਖੁੱਲ੍ਹਦੀਆਂ ਹਨ। UTF-8 ਟੈਕਸਟ, ਹਵਾਲਾ-ਚਿੰਨ੍ਹਾਂ ਵਾਲੇ ਕਾਮੇ, ਨੋਟਾਂ ਵਿੱਚ ਲਾਈਨ ਬ੍ਰੇਕ ਅਤੇ ਕੋਡਾਂ ਵਿੱਚ ਮੂਹਰਲੇ ਸਿਫ਼ਰ ਸਭ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦੇ ਹਨ, ਅਤੇ ਫ਼ਾਰਮੂਲੇ ਵਾਂਗ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੇ ਸੈੱਲਾਂ ਨੂੰ ਨਿਰਪੱਖ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਸਪ੍ਰੈਡਸ਼ੀਟ ਉਨ੍ਹਾਂ ਨੂੰ ਟੈਕਸਟ ਵਜੋਂ ਖੋਲ੍ਹੇ।",
  "exports.about2": "Excel ਫ਼ਾਈਲਾਂ ਵਿੱਚ, SKU, UPC, ISBN ਅਤੇ ਬਾਰਕੋਡ ਟੈਕਸਟ ਸੈੱਲ ਹੁੰਦੇ ਹਨ — ਕਦੇ ਵੀ ਵਿਗਿਆਨਕ ਨੋਟੇਸ਼ਨ ਨਹੀਂ ਅਤੇ ਕਦੇ ਵੀ ਕੱਟੇ ਹੋਏ ਸਿਫ਼ਰ ਨਹੀਂ — ਕਾਲਮ ਚੌੜਾਈਆਂ, ਹੈਡਰ ਫ਼ਿਲਟਰ ਅਤੇ ਮੁਦਰਾ ਜਾਂ ਮਾਤਰਾ ਫ਼ਾਰਮੈਟ ਲਾਗੂ ਕੀਤੇ ਹੋਏ। ਪੂਰੀ ਇਨਵੈਂਟਰੀ ਵਰਕਬੁੱਕ ਉਤਪਾਦਾਂ, ਸਟਾਕ ਪੱਧਰਾਂ, ਸਥਾਨਾਂ ਅਤੇ ਮੂਵਮੈਂਟਾਂ ਨੂੰ ਵੱਖ-ਵੱਖ ਸ਼ੀਟਾਂ 'ਤੇ ਰੱਖਦੀ ਹੈ।",
  "exports.about3": "ਬਹੁਤ ਵੱਡੇ ਨਿਰਯਾਤ ਹਰ ਡੇਟਾਸੈੱਟ ਲਈ 20,000 ਕਤਾਰਾਂ 'ਤੇ ਰੁਕ ਜਾਂਦੇ ਹਨ — ਜਦੋਂ ਅਜਿਹਾ ਹੁੰਦਾ ਹੈ ਤਾਂ ਫ਼ਾਈਲ ਦਾ ਨਾਂ ਇਹ ਦੱਸਦਾ ਹੈ (truncated-20000), ਤਾਂ ਜੋ ਅਧੂਰੀ ਫ਼ਾਈਲ ਕਦੇ ਪੂਰੀ ਵਜੋਂ ਨਾ ਲੰਘੇ।",
  "exports.about4": "ਬੈਕਅੱਪ ਤੁਹਾਡੇ ਡੇਟਾ ਦਾ ਇੱਕ ਸਨੈਪਸ਼ਾਟ ਹੈ, ਇੱਕ-ਕਲਿੱਕ ਰੀਸਟੋਰ ਨਹੀਂ। ਇਸ ਨੂੰ ਰੀਸਟੋਰ ਕਰਨਾ ਹੱਥੀਂ, ਪਹਿਲਾਂ ਸਮੀਖਿਆ ਵਾਲਾ ਕੰਮ ਹੈ, ਇਸ ਲਈ ਫ਼ਾਈਲ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖੋ — ਐਪ ਵਿੱਚ ਅਜੇ ਕੁਝ ਵੀ ਇਸ ਤੋਂ ਮਿਟਾਏ ਗਏ ਕਾਰੋਬਾਰ ਨੂੰ ਦੁਬਾਰਾ ਨਹੀਂ ਬਣਾ ਸਕਦਾ। ਐਪ ਕੋਡ ਅਤੇ Base44 ਪਲੇਟਫ਼ਾਰਮ ਦੇ ਬੈਕਅੱਪ ਇਨ੍ਹਾਂ ਫ਼ਾਈਲਾਂ ਤੋਂ ਵੱਖਰੇ ਤੌਰ 'ਤੇ ਸੰਭਾਲੇ ਜਾਂਦੇ ਹਨ।",
  "exports.about5": "ਫ਼ੋਟੋਆਂ ਅਤੇ ਅਟੈਚਮੈਂਟ ਉਨ੍ਹਾਂ ਦੇ ਸਟੋਰ ਕੀਤੇ ਲਿੰਕਾਂ ਵਜੋਂ ਸੂਚੀਬੱਧ ਹੁੰਦੀਆਂ ਹਨ — ਤਸਵੀਰ ਫ਼ਾਈਲਾਂ ਆਪ ਡਾਊਨਲੋਡ ਵਿੱਚ ਪੈਕ ਨਹੀਂ ਹੁੰਦੀਆਂ।",
  "exports.backupTitle": "ਪੂਰਾ ਬੈਕਅੱਪ",
  "exports.backupDesc": "ਇਸ ਕਾਰੋਬਾਰ ਦੇ ਉਤਪਾਦਾਂ, ਸਥਾਨਾਂ, ਸਟਾਕ ਪੱਧਰਾਂ, ਪੂਰੇ ਮੂਵਮੈਂਟ ਲੇਜ਼ਰ, ਸਪਲਾਇਰਾਂ, ਖਰੀਦਦਾਰੀ, ਆਰਡਰਾਂ, ਵਾਪਸੀਆਂ, ਗਿਣਤੀਆਂ ਅਤੇ ਲਿਸਟਿੰਗਾਂ ਵਾਲੀ ਇੱਕ ਫ਼ਾਈਲ — ਇਸ ਦੀਆਂ ਪ੍ਰੋਫ਼ਾਈਲ ਸੈਟਿੰਗਾਂ ਸਮੇਤ। ਇਸ ਨੂੰ ਕਿਤੇ ਅਜਿਹੀ ਥਾਂ ਰੱਖੋ ਜੋ ਤੁਹਾਡੇ ਨਿਯੰਤਰਣ ਵਿੱਚ ਹੋਵੇ।",
  "exports.backupIncludes1": "ਉਤਪਾਦ, ਕੋਡ, ਲਾਗਤਾਂ ਅਤੇ ਨੋਟ",
  "exports.backupIncludes2": "ਸਥਾਨ ਅਤੇ ਹਰ ਸਥਾਨ ਦੀ ਮਾਤਰਾ",
  "exports.backupIncludes3": "ਹਰ ਮੂਵਮੈਂਟ, ਕਰਨ ਵਾਲੇ ਅਤੇ ਸਮੇਂ ਸਮੇਤ",
  "exports.backupIncludes4": "ਖਰੀਦਦਾਰੀ, ਆਰਡਰ, ਵਾਪਸੀਆਂ ਅਤੇ ਗਿਣਤੀਆਂ",
  "exports.buildingBackup": "ਬੈਕਅੱਪ ਬਣਾਇਆ ਜਾ ਰਿਹਾ ਹੈ…",
