  "import.eyebrow": "ਡੇਟਾ",
  "import.title": "ਆਯਾਤ ਕੇਂਦਰ",
  "import.subtitleStart": "ਤਿੰਨ ਵੱਖ-ਵੱਖ ਸਪ੍ਰੈਡਸ਼ੀਟ ਕਾਰਵਾਈਆਂ, ਤਾਂ ਜੋ ਕੀਮਤ ਸੋਧ ਕਦੇ ਸਟਾਕ ਰਸੀਦ ਵਜੋਂ ਨਾ ਆਵੇ। ਸਭ ਕੁਝ ਸਿਰਫ਼",
  "import.subtitleRest": " ਵਿੱਚ ਹੀ ਆਉਂਦਾ ਹੈ, ਅਤੇ ਡਰਾਈ ਰਨ ਪਾਸ ਹੋਣ ਤੱਕ ਕੁਝ ਵੀ ਨਹੀਂ ਲਿਖਿਆ ਜਾਂਦਾ।",
  "import.createBusinessFirst": "ਪਹਿਲਾਂ ਕਾਰੋਬਾਰ ਬਣਾਓ — ਆਯਾਤ ਕੀਤੇ ਉਤਪਾਦ ਕਿਸੇ ਕਾਰੋਬਾਰ ਦੇ ਹੁੰਦੇ ਹਨ।",
  "import.createBusinessFirstShort": "ਪਹਿਲਾਂ ਕਾਰੋਬਾਰ ਬਣਾਓ।",
  "import.whatEachDoes": "ਹਰ ਕਾਰਵਾਈ ਕੀ ਕਰਦੀ ਹੈ",
  "import.createTitle": "ਨਵੇਂ ਉਤਪਾਦ ਬਣਾਓ",
  "import.createDesc": "ਉਹ ਕਤਾਰਾਂ ਜੋੜਦੀ ਹੈ ਜੋ ਅਜੇ ਕੈਟਾਲਾਗ ਵਿੱਚ ਨਹੀਂ ਹਨ। ਪਹਿਲਾਂ ਤੋਂ ਵਰਤੋਂ ਵਿੱਚ ਡੁਪਲੀਕੇਟ SKU ਅਤੇ ਬਾਰਕੋਡ ਛੱਡ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਸ਼ੁਰੂਆਤੀ ਸਟਾਕ ਤੁਹਾਡੇ ਚੁਣੇ ਸਥਾਨ ਵਿੱਚ ਰਸੀਦ ਵਜੋਂ ਆ ਸਕਦਾ ਹੈ।",
  "import.updateTitle": "ਮੌਜੂਦਾ ਉਤਪਾਦ ਅੱਪਡੇਟ ਕਰੋ",
  "import.updateDesc": "ਹਰ ਕਤਾਰ ਨੂੰ SKU ਜਾਂ ਰਿਕਾਰਡ ID ਨਾਲ ਮਿਲਾਉਂਦੀ ਹੈ ਅਤੇ ਪ੍ਰਸਤਾਵਿਤ ਨਵੇਂ ਮੁੱਲ ਦੇ ਨਾਲ ਪੁਰਾਣਾ ਮੁੱਲ ਵਿਖਾਉਂਦੀ ਹੈ। ਖ਼ਾਲੀ ਸੈੱਲ ਸੰਭਾਲੇ ਮੁੱਲ ਨੂੰ ਉਵੇਂ ਹੀ ਛੱਡ ਦਿੰਦੇ ਹਨ, ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਖ਼ਾਲੀ ਥਾਵਾਂ ਨੂੰ ਸਾਫ਼ ਕਰਨ ਲਈ ਨਾ ਕਹੋ, ਅਤੇ ਮਾਤਰਾਵਾਂ ਨੂੰ ਕਦੇ ਛੂਹਿਆ ਨਹੀਂ ਜਾਂਦਾ।",
  "import.receiveModeTitle": "ਸਟਾਕ ਪ੍ਰਾਪਤ ਕਰੋ",
  "import.receiveModeDesc": "ਆਉਂਦੀਆਂ ਮਾਤਰਾਵਾਂ ਨੂੰ ਇੱਕ ਸਥਾਨ ਵਿੱਚ ਜੋੜਦੀ ਹੈ ਅਤੇ ਹਰ ਲਾਈਨ ਲਈ ਮੂਵਮੈਂਟ ਲੇਜ਼ਰ ਵਿੱਚ ਰਸੀਦ ਲਿਖਦੀ ਹੈ। ਹਰ ਬੈਚ 'ਤੇ ਨਿਸ਼ਾਨ ਲਗਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਉਹੀ ਸ਼ੀਟ ਦੋ ਵਾਰ ਪ੍ਰਾਪਤ ਨਾ ਹੋ ਸਕੇ।",
  "import.excelNote": "Excel ਵਰਕਬੁੱਕਾਂ (.xlsx) ਸਿੱਧੀਆਂ ਪੜ੍ਹੀਆਂ ਜਾਂਦੀਆਂ ਹਨ — ਵਰਕਸ਼ੀਟ ਚੁਣੋ ਅਤੇ ਕਾਲਮ ਤੁਹਾਡੇ ਲਈ ਮਿਲਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ। ਕੋਡ ਪੂਰੇ ਰਹਿੰਦੇ ਹਨ: ਟੈਕਸਟ ਵਜੋਂ ਸੰਭਾਲਿਆ UPC ਆਪਣੇ ਅੰਕ ਅਤੇ ਮੂਹਰਲੇ ਸਿਫ਼ਰ ਰੱਖਦਾ ਹੈ। ਜਿਹੜੀਆਂ ਕਤਾਰਾਂ ਆਯਾਤ ਨਹੀਂ ਹੋ ਸਕਦੀਆਂ, ਉਹ ਕਾਰਨ ਸਮੇਤ ਸੂਚੀਬੱਧ ਹੁੰਦੀਆਂ ਹਨ",
  "import.excelNoteDownload": " ਅਤੇ ਫ਼ਾਈਲ ਵਜੋਂ ਡਾਊਨਲੋਡ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।",
  "import.excelNoteFix": ", ਤਾਂ ਜੋ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਠੀਕ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰ ਸਕੋ।",
  "import.matchColumns": "ਕਾਲਮ ਮਿਲਾਓ",
