  "import.receiveMissingMessage": "ਇੱਕ ਕਾਲਮ ਨੂੰ SKU ਜਾਂ ਰਿਕਾਰਡ ID ਨਾਲ, ਅਤੇ ਇੱਕ ਨੂੰ ਪ੍ਰਾਪਤ ਮਾਤਰਾ ਨਾਲ ਮਿਲਾਓ।",
