  "reports.biggest": "ਸਭ ਤੋਂ ਵੱਡਾ {group}",
  "reports.nothingToRank": "ਅਜੇ ਦਰਜਾ ਦੇਣ ਲਈ ਕੁਝ ਨਹੀਂ",
  "reports.missingMoney": "ਇਸ ਦ੍ਰਿਸ਼ ਵਿੱਚ {units} ਇਕਾਈਆਂ ਦਾ ਕੋਈ {label} ਦਰਜ ਨਹੀਂ ਹੈ। ਗੁੰਮ ਪੈਸੇ ਨੂੰ ਕਦੇ ਸਿਫ਼ਰ ਨਹੀਂ ਮੰਨਿਆ ਜਾਂਦਾ — ਉਨ੍ਹਾਂ ਨੂੰ ਮੁਫ਼ਤ ਗਿਣਨ ਦੀ ਬਜਾਏ ਅੰਕੜਿਆਂ ਤੋਂ ਬਾਹਰ ਛੱਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਉਨ੍ਹਾਂ ਉਤਪਾਦਾਂ 'ਤੇ ਅੰਕੜਾ ਜੋੜੋ ਅਤੇ ਕੁੱਲ ਭਰ ਜਾਣਗੇ।",
  "reports.movementsCapped": "ਸਿਰਫ਼ ਸਭ ਤੋਂ ਨਵੇਂ {cap} ਲੇਜ਼ਰ ਦਾਖ਼ਲੇ ਪੜ੍ਹੇ ਗਏ, ਇਸ ਲਈ ਇਨ੍ਹਾਂ ਤੋਂ ਪੁਰਾਣੀਆਂ ਮੂਵਮੈਂਟਾਂ ਕੁੱਲਾਂ ਵਿੱਚ ਨਹੀਂ ਹਨ। ਕਿਸੇ ਸਮੇਂ ਲਈ ਸਹੀ ਅੰਕੜੇ ਵੇਖਣ ਲਈ ਮਿਆਦ ਨੂੰ ਸੰਕੁਚਿਤ ਕਰੋ।",
  "reports.footnote": "ਵਿਕਰੀ ਹਰ ਉਤਪਾਦ ਦੀ ਮੌਜੂਦਾ ਪ੍ਰਚੂਨ ਕੀਮਤ ਵਰਤਦੀ ਹੈ, ਰਸੀਦਾਂ ਸਟਾਕ ਆਉਣ ਵੇਲੇ ਦਰਜ ਲਾਗਤ ਵਰਤਦੀਆਂ ਹਨ, ਅਤੇ ਨੁਕਸਾਨ ਮੌਜੂਦਾ ਇਕਾਈ ਲਾਗਤ ਵਰਤਦੇ ਹਨ। ਗੁੰਮ ਪੈਸੇ ਨੂੰ ਕਦੇ ਸਿਫ਼ਰ ਨਹੀਂ ਮੰਨਿਆ ਜਾਂਦਾ — ਅੰਕੜਾ ਪਤਾ ਲੱਗਣ ਤੱਕ ਖੇਤਰ ਖ਼ਾਲੀ ਛੱਡੋ। ਰਿਪੋਰਟ ਇੱਕ ਦ੍ਰਿਸ਼ ਹੈ, ਦਸਤਾਵੇਜ਼ ਨਹੀਂ: ਜਦੋਂ ਤੁਸੀਂ ਇੱਕ ਚਲਾਉਂਦੇ ਹੋ ਤਾਂ ਤੁਹਾਡੇ ਰਿਕਾਰਡਾਂ ਵਿੱਚ ਕੁਝ ਵੀ ਨਹੀਂ ਲਿਖਿਆ ਜਾਂਦਾ।",
