  "print.templateIsBusiness": "{label} Business ਵਿਸ਼ੇਸ਼ਤਾ ਹੈ",
  "print.supplierBlockedDesc": "ਸਪਲਾਇਰ ਦਸਤਾਵੇਜ਼ Business ਪਲਾਨ ਨਾਲ ਜਾਂਦੇ ਹਨ — ਸਪਲਾਇਰ, ਖਰੀਦਦਾਰੀ ਅਤੇ ਖਰੀਦ ਆਰਡਰ। ਤੁਹਾਡੇ ਕੋਲ ਹੁਣ ਜੋ ਕੁਝ ਹੈ ਉਹ ਕੰਮ ਕਰਦਾ ਰਹੇਗਾ।",
  "print.seeBusiness": "ਵੇਖੋ Business ਵਿੱਚ ਕੀ-ਕੀ ਸ਼ਾਮਲ ਹੈ",
  "print.nothingToPrint": "ਅਜੇ ਛਾਪਣ ਲਈ ਕੁਝ ਨਹੀਂ",
  "print.pickOrderHint": "ਦਸਤਾਵੇਜ਼ ਦੀ ਝਲਕ ਵੇਖਣ ਲਈ ਸੂਚੀ ਵਿੱਚੋਂ ਖਰੀਦ ਆਰਡਰ ਚੁਣੋ।",
  "print.pickCustomerOrderHint": "ਦਸਤਾਵੇਜ਼ ਦੀ ਝਲਕ ਵੇਖਣ ਲਈ ਸੂਚੀ ਵਿੱਚੋਂ ਗਾਹਕ ਆਰਡਰ ਚੁਣੋ।",
  "print.pickReturnHint": "ਦਸਤਾਵੇਜ਼ ਦੀ ਝਲਕ ਵੇਖਣ ਲਈ ਸੂਚੀ ਵਿੱਚੋਂ ਦਰਜ ਵਾਪਸੀ ਚੁਣੋ।",
  "print.chooseStyleHint": "ਸ਼ੈਲੀ ਚੁਣੋ, ਫਿਰ ਸੂਚੀ ਵਿੱਚੋਂ ਉਤਪਾਦ ਚੁਣੋ। ਝਲਕ ਬਿਲਕੁਲ ਉਹੀ ਵਿਖਾਉਂਦੀ ਹੈ ਜੋ ਪ੍ਰਿੰਟਰ ਵਿੱਚੋਂ ਨਿਕਲੇਗਾ।",
  "print.howToReach": "ਆਪਣੇ ਪ੍ਰਿੰਟਰ ਤੱਕ ਕਿਵੇਂ ਪਹੁੰਚਣਾ ਹੈ",
  "print.howIntro": "ਇਹ ਐਪ ਉਨ੍ਹਾਂ ਪ੍ਰਿੰਟਰਾਂ ਨਾਲ ਜੁੜਦੀ ਹੈ ਜੋ ਤੁਹਾਡੇ ਕੋਲ ਪਹਿਲਾਂ ਤੋਂ ਹਨ — ਇਹ ਆਪ ਪ੍ਰਿੰਟਰ ਨਹੀਂ ਹੈ। ਇੱਕ ਤੱਕ ਪਹੁੰਚਣ ਦੇ ਚਾਰ ਤਰੀਕੇ ਹਨ, ਅਤੇ ਲੇਬਲ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕਿਸੇ 'ਤੇ ਵੀ ਦੋਵਾਂ ਪਲਾਨਾਂ 'ਤੇ ਛਪਦੇ ਹਨ। ਪੈਕਿੰਗ ਸਲਿੱਪਾਂ, ਖਰੀਦ ਆਰਡਰ, ਸਪਲਾਇਰ ਦਸਤਾਵੇਜ਼ ਅਤੇ ਰਿਪੋਰਟਾਂ ਸਿਰਫ਼ Business ਲਈ ਹਨ, ਕਨੈਕਸ਼ਨ ਭਾਵੇਂ ਕੋਈ ਵੀ ਹੋਵੇ।",
  "print.howBluetoothLead": "Bluetooth।",
  "print.howBluetoothBody": "ਇਸ ਪੰਨੇ ਤੋਂ, ਡੈਸਕਟਾਪ Chrome ਜਾਂ Edge 'ਤੇ ਅਤੇ Android Chrome 'ਤੇ: ਆਪਣਾ ਲੇਬਲ ਪ੍ਰਿੰਟਰ ਚੁਣੋ ਅਤੇ ਲੇਬਲ ਸਿੱਧੇ ਇਸ 'ਤੇ ਜਾਂਦੇ ਹਨ। ਇਹ iOS Safari ਵਿੱਚ ਕੰਮ ਨਹੀਂ ਕਰਦਾ — iPhone 'ਤੇ, Bluetooth ਪ੍ਰਿੰਟਿੰਗ ਇਸ ਦੀ ਬਜਾਏ ਮੋਬਾਈਲ ਐਪ ਨਾਲ ਆਉਂਦੀ ਹੈ। ਜਿਹੜਾ ਪ੍ਰਿੰਟਰ ਸਿਰਫ਼ Zebra ZPL ਜਾਂ Brother ਦੀ ਆਪਣੀ ਭਾਸ਼ਾ ਬੋਲਦਾ ਹੈ, ਉਹ ਇਸ ਪੰਨੇ ਵੱਲੋਂ ਭੇਜੇ ਲੇਬਲਾਂ ਨੂੰ ਨਹੀਂ ਸਮਝੇਗਾ; ਇਸ ਨੂੰ ਕੰਮ ਕਰਨ ਵਾਲਾ ਕਹਿਣ ਤੋਂ ਪਹਿਲਾਂ ਅਸਲੀ ਪ੍ਰਿੰਟਰਾਂ ਦੇ ਵਿਰੁੱਧ ਜਾਂਚਿਆ ਜਾਂਦਾ ਹੈ।",
  "print.howWifiLead": "Wi-Fi।",
  "print.howWifiBody": "ਪ੍ਰਿੰਟਰ ਨੂੰ ਆਪਣੀ ਦੁਕਾਨ ਦੇ Wi-Fi 'ਤੇ ਸਥਾਪਿਤ ਕਰੋ, ਫਿਰ ਪ੍ਰਿੰਟ ਬਟਨ ਵਰਤੋ — ਇਹ ਇਸ ਕੰਪਿਊਟਰ 'ਤੇ ਸਥਾਪਿਤ ਪ੍ਰਿੰਟਰ ਰਾਹੀਂ, ਦੁਕਾਨ ਨੈੱਟਵਰਕ 'ਤੇ ਛਾਪਦਾ ਹੈ। iPhone 'ਤੇ, AirPrint ਬਿਲਟ-ਇਨ ਹੈ: ਉਸੇ Wi-Fi 'ਤੇ AirPrint ਪ੍ਰਿੰਟਰ ਬਿਨਾਂ ਕਿਸੇ ਤਾਰ ਅਤੇ ਬਿਨਾਂ ਕਿਸੇ ਐਪ ਦੇ ਪ੍ਰਿੰਟ ਸ਼ੀਟ ਵਿੱਚ ਹੀ ਵਿਖਾਈ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਐਪ ਨੂੰ AirPrint-ਵਿਸ਼ੇਸ਼ ਕੋਡ ਦੀ ਲੋੜ ਨਹੀਂ। ਪ੍ਰਿੰਟਰ ਨੂੰ AirPrint ਦਾ ਸਮਰਥਨ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ (ਜ਼ਿਆਦਾਤਰ ਨਵੇਂ ਕਰਦੇ ਹਨ) ਅਤੇ ਫ਼ੋਨ ਅਤੇ ਪ੍ਰਿੰਟਰ ਇੱਕੋ Wi-Fi 'ਤੇ ਹੋਣੇ ਚਾਹੀਦੇ ਹਨ।",
  "print.howEthernetLead": "Ethernet।",
  "print.howEthernetBody": "ਪ੍ਰਿੰਟਰ ਨੂੰ Ethernet ਤਾਰ ਨਾਲ ਆਪਣੇ ਦੁਕਾਨ ਨੈੱਟਵਰਕ ਨਾਲ ਜੋੜੋ, ਇਸ ਨੂੰ ਕੰਪਿਊਟਰ 'ਤੇ ਸਥਾਪਿਤ ਕਰੋ, ਅਤੇ ਪ੍ਰਿੰਟ ਬਟਨ ਰਾਹੀਂ ਛਾਪੋ। Ethernet ਡੈਸਕਟਾਪ ਅਤੇ ਕੰਪਿਊਟਰ ਦਾ ਰਸਤਾ ਹੈ — iPhone Ethernet ਤਾਰਾਂ ਨਹੀਂ ਵਰਤਦੇ।",
  "print.howUsbLead": "USB।",
  "print.howUsbBody": "ਪ੍ਰਿੰਟਰ ਨੂੰ ਇਸ ਦੀ ਤਾਰ ਨਾਲ ਕੰਪਿਊਟਰ ਵਿੱਚ ਲਗਾਓ ਅਤੇ ਪ੍ਰਿੰਟ ਬਟਨ ਵਰਤੋ — ਇਹ ਉੱਥੇ ਸਥਾਪਿਤ ਪ੍ਰਿੰਟਰ ਰਾਹੀਂ ਛਾਪਦਾ ਹੈ। USB OTG ਕੇਬਲ ਵਾਲੇ Android ਫ਼ੋਨ 'ਤੇ, ਉੱਪਰਲਾ USB ਬਟਨ ਸਿੱਧਾ ਪ੍ਰਿੰਟਰ ਨਾਲ ਗੱਲ ਕਰਦਾ ਹੈ। iPhone ਸਿੱਧੇ USB 'ਤੇ ਨਹੀਂ ਛਾਪ ਸਕਦੇ — ਉੱਥੇ ਕੋਈ WebUSB ਨਹੀਂ — ਇਸ ਲਈ Wi-Fi / AirPrint ਵਰਤੋ, ਜਾਂ ਮੋਬਾਈਲ ਐਪ ਤੋਂ Bluetooth ਵਰਤੋ।",
  "print.howCordsLead": "ਤਾਰਾਂ ਅਜੇ ਵੀ iPhone ਦੀ ਸੇਵਾ ਕਰਦੀਆਂ ਹਨ, ਇੱਕ ਕਦਮ ਹਟ ਕੇ।",
  "print.howCordsBody": "ਦੁਕਾਨ ਕੰਪਿਊਟਰ ਵਿੱਚ ਲੱਗਿਆ USB ਪ੍ਰਿੰਟਰ, ਜਾਂ ਨੈੱਟਵਰਕ ਨਾਲ ਜੁੜਿਆ Ethernet ਪ੍ਰਿੰਟਰ, ਤੁਹਾਡੇ iPhone 'ਤੇ ਦੁਕਾਨ Wi-Fi 'ਤੇ ਵਿਖਾਈ ਦਿੰਦਾ ਹੈ (AirPrint / ਸਾਂਝਾ ਪ੍ਰਿੰਟਰ) — ਤਾਰਾਂ ਪ੍ਰਿੰਟਰ ਨੂੰ ਨੈੱਟਵਰਕ 'ਤੇ ਮਜ਼ਬੂਤੀ ਨਾਲ ਪਾਉਂਦੀਆਂ ਹਨ, ਅਤੇ ਫ਼ੋਨ ਇਸ ਤੱਕ ਬੇਤਾਰ ਪਹੁੰਚਦਾ ਹੈ।",
  "print.howOfflineLead": "ਜੇ ਇੰਟਰਨੈੱਟ ਬੰਦ ਹੋ ਜਾਵੇ,",
  "print.howOfflineBody": "ਇਸ ਪੰਨੇ 'ਤੇ ਪਹਿਲਾਂ ਤੋਂ ਮੌਜੂਦ ਲੇਬਲ ਅਤੇ ਦਸਤਾਵੇਜ਼ ਅਜੇ ਵੀ ਛਪਦੇ ਹਨ — ਪ੍ਰਿੰਟ ਬਟਨ, ਲੇਬਲ PDF, Bluetooth ਅਤੇ USB ਨੂੰ ਕਿਸੇ ਕਨੈਕਸ਼ਨ ਦੀ ਲੋੜ ਨਹੀਂ। ਜਿਸ ਚੀਜ਼ ਨੂੰ ਇੰਟਰਨੈੱਟ ਦੀ ਲੋੜ ਹੈ ਉਹ ਹੈ ਪਹਿਲਾਂ ਪੰਨੇ ਅਤੇ ਇਸ ਦੇ ਉਤਪਾਦਾਂ ਨੂੰ ਲੋਡ ਕਰਨਾ। ਪੂਰਾ ਆਫ਼ਲਾਈਨ ਮੋਡ (ਬਿਲਕੁਲ ਕਨੈਕਸ਼ਨ ਤੋਂ ਬਿਨਾਂ ਐਪ ਵਿੱਚ ਕੰਮ ਕਰਨਾ) ਇੱਕ ਵੱਖਰਾ, ਵੱਡਾ ਨਿਰਮਾਣ ਹੈ ਅਤੇ ਇੱਥੇ ਇਸ ਦਾ ਦਾਅਵਾ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।",
