  "settings.businesses.planLoadError": "ਅਸੀਂ ਤੁਹਾਡੀ ਯੋਜਨਾ ਭੱਤਾ ਲੋਡ ਨਹੀਂ ਕਰ ਸਕੇ, ਇਸ ਲਈ ਕਾਰੋਬਾਰੀ ਸੀਮਾ ਅੰਦਾਜ਼ਾ ਲਗਾਉਣ ਦੀ ਬਜਾਏ ਲੁਕਾਈ ਗਈ ਹੈ।",
  "settings.businesses.planUnavailable": "ਯੋਜਨਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ",
