  "payroll.dd.formTitle": "ਸਿੱਧੀ ਜਮ੍ਹਾਂ ਅਧਿਕਾਰ ਫਾਰਮ",
  "payroll.dd.help": "ਹਰ ਟੀਮ ਮੈਂਬਰ ਦੇ ਬੈਂਕ ਵੇਰਵੇ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਇਕੱਠੇ ਕਰੋ। ਜਮ੍ਹਾਂ ਕੀਤੇ ਵੇਰਵੇ ਸਿਰਫ਼ ਮਾਲਕ ਕੋਲ ਜਾਂਦੇ ਹਨ - ਹੋਰ ਕੋਈ ਇਹਨਾਂ ਨੂੰ ਨਹੀਂ ਦੇਖ ਸਕਦਾ।",
