  "payroll.dd.routing": "ਰੂਟਿੰਗ ਨੰਬਰ (9 ਅੰਕ)",
  "payroll.dd.savings": "ਬੱਚਤ",
  "payroll.dd.steps.body": "1. ਤੁਹਾਨੂੰ ਇੱਕ ਕਾਰੋਬਾਰੀ ਬੈਂਕ ਖਾਤਾ ਚਾਹੀਦਾ ਹੈ ਜੋ ACH ਭੁਗਤਾਨ ਭੇਜ ਸਕੇ। 2. ਹਰ ਟੀਮ ਮੈਂਬਰ ਤੋਂ ਇੱਕ ਦਸਤਖਤ ਕੀਤਾ ਅਧਿਕਾਰ ਫਾਰਮ ਇਕੱਠਾ ਕਰੋ - ਇੱਕ ਰੱਦ ਕੀਤਾ ਚੈੱਕ ਨੰਬਰਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। 3. ਤਨਖਾਹ ਵਾਲੇ ਦਿਨ ਤੋਂ 2-3 ਕਾਰੋਬਾਰੀ ਦਿਨ ਪਹਿਲਾਂ ਤਨਖਾਹ ਸੂਚੀ ਭੇਜੋ ਤਾਂ ਜੋ ਪੈਸੇ ਸਮੇਂ ਸਿਰ ਪਹੁੰਚ ਜਾਣ। 4. ਜ਼ਿਆਦਾਤਰ ਰਾਜਾਂ ਨੂੰ ਟੀਮ ਮੈਂਬਰ ਦੀ ਲਿਖਤੀ ਸਹਿਮਤੀ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਇਹ ਐਪ ਫਾਰਮ ਇਕੱਠੇ ਕਰਦੀ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਕਦਮਾਂ ਵਿੱਚ ਲੈ ਕੇ ਜਾਂਦੀ ਹੈ - ਪੈਸੇ ਅਸਲ ਵਿੱਚ ਭੇਜਣਾ ਤੁਹਾਡੇ ਆਪਣੇ ਬੈਂਕ ਰਾਹੀਂ ਹੁੰਦਾ ਹੈ।",
  "payroll.dd.steps.title": "ਸਿੱਧੀ ਜਮ੍ਹਾਂ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ",
