  "workforce.selfClockOff": "ਇਸ ਕਾਰੋਬਾਰ ਲਈ ਸਵੈ ਕਲੌਕ-ਇਨ ਬੰਦ ਹੈ। ਜੇ ਤੁਹਾਨੂੰ ਇਸਦੀ ਲੋੜ ਹੈ ਤਾਂ ਮਾਲਕ ਨੂੰ ਪੁੱਛੋ।",
  "workforce.settings.saved": "ਸੈਟਿੰਗਾਂ ਸੁਰੱਖਿਅਤ ਕੀਤੀਆਂ ਗਈਆਂ।",
  "workforce.settings.selfClock": "ਸਟਾਫ਼ ਨੂੰ ਆਪ ਹੀ ਕਲੌਕ ਇਨ ਅਤੇ ਆਊਟ ਕਰਨ ਦਿਓ",
