  "workforce.todayShift": "ਅੱਜ ਦੀ ਸ਼ਿਫਟ: {start} - {end}",
  "workforce.unscheduledNote": "ਅੱਜ ਕੋਈ ਸ਼ਿਫਟ ਨਿਰਧਾਰਤ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਇਹ ਸਮਾਂ ਬਿਨਾਂ ਸ਼ਡਿਊਲ ਵਜੋਂ ਨਿਸ਼ਾਨਬੱਧ ਕੀਤਾ ਜਾਵੇਗਾ।",
  "workforce.inbox.help": "ਤੁਹਾਡੀ ਟੀਮ ਲਈ ਕਲੌਕ ਇਵੈਂਟ, ਛੁੱਟੀ ਦੇ ਜਵਾਬ, ਕੰਮ, ਤਨਖਾਹ ਸਟੱਬ ਅਤੇ ਸ਼ਡਿਊਲ ਬਦਲਾਅ, ਸਭ ਤੋਂ ਨਵੇਂ ਪਹਿਲਾਂ।",
  "workforce.messages.back": "ਸਾਰੀਆਂ ਗੱਲਬਾਤਾਂ",
  "workforce.messages.empty": "ਅਜੇ ਕੋਈ ਗੱਲਬਾਤ ਨਹੀਂ। ਉੱਪਰ ਵਾਲੇ ਬਟਨ ਨਾਲ ਇੱਕ ਸ਼ੁਰੂ ਕਰੋ।",
  "workforce.messages.emptyThread": "ਅਜੇ ਕੋਈ ਸੁਨੇਹੇ ਨਹੀਂ। ਸ਼ੁਰੂਆਤ ਕਰਨ ਲਈ ਹੈਲੋ ਕਹੋ।",
  "workforce.messages.help": "ਤੁਹਾਡੀ ਟੀਮ ਨਾਲ ਨਿੱਜੀ ਇੱਕ-ਨਾਲ-ਇੱਕ ਸੁਨੇਹੇ — ਕਿਸੇ ਹੋਰ ਐਪ ਦੀ ਲੋੜ ਨਹੀਂ। ਗੱਲਬਾਤ ਵਿੱਚ ਸਿਰਫ਼ ਦੋ ਲੋਕ ਹੀ ਇਸਨੂੰ ਪੜ੍ਹ ਸਕਦੇ ਹਨ, ਨਾਲ ਹੀ ਕਾਰੋਬਾਰ ਦਾ ਮਾਲਕ, ਜੋ ਆਪਣੇ ਸਟੋਰ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦਾ ਹੈ।",
  "workforce.messages.new": "ਨਵਾਂ ਸੁਨੇਹਾ",
  "workforce.messages.oversight": "ਮਾਲਕ ਦ੍ਰਿਸ਼",
  "workforce.messages.oversightNote": "ਤੁਸੀਂ ਇਹ ਗੱਲਬਾਤ ਪੜ੍ਹ ਸਕਦੇ ਹੋ ਕਿਉਂਕਿ ਤੁਸੀਂ ਇਸ ਕਾਰੋਬਾਰ ਦੇ ਮਾਲਕ ਹੋ। ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਸ਼ਾਮਲ ਨਹੀਂ ਹੋ ਸਕਦੇ।",
