  "recovery.emailMeCodeHint": "ਜੇ ਤੁਸੀਂ ਇੱਕ ਬੈਕਅੱਪ ਈਮੇਲ ਸੈੱਟ ਕੀਤੀ ਹੈ, ਅਸੀਂ ਉੱਥੇ ਇੱਕ 6-ਅੰਕਾਂ ਵਾਲਾ ਕੋਡ ਭੇਜਾਂਗੇ। ਤੁਹਾਡੇ ਖਾਤੇ ਦੀ ਸੁਰੱਖਿਆ ਲਈ, ਇਹ ਪੰਨਾ ਹਮੇਸ਼ਾ ਉਸੇ ਤਰ੍ਹਾਂ ਜਵਾਬ ਦਿੰਦਾ ਹੈ — ਚਾਹੇ ਇੱਕ ਕੋਡ ਭੇਜਿਆ ਗਿਆ ਹੋਵੇ ਜਾਂ ਨਾ।",
