  "support.category.broken": "ਕੁਝ ਟੁੱਟਿਆ ਹੋਇਆ ਹੈ",
  "support.category.idea": "ਇੱਕ ਵਿਚਾਰ ਜਾਂ ਸੁਝਾਅ",
  "support.category.looksWrong": "ਕੁਝ ਗਲਤ ਲੱਗਦਾ ਹੈ",
