  "pricing.businessOnly": "ਕਲੀਅਰੈਂਸ ਅਤੇ ਰੋਲਬੈਕ ਕੀਮਤ Business ਯੋਜਨਾ ਦਾ ਹਿੱਸਾ ਹੈ।",
  "pricing.clearanceBadge": "ਕਲੀਅਰੈਂਸ",
